{'code': "from qgis.PyQt.QtWidgets import QAction, QToolBar
mw = iface.mainWindow()
cands = [a for a in mw.findChildren(QAction) if 'レイヤ管理ツールバー' in a.text()]
action = mw.findChild(QAction, 'mActionToggleLayerToolBar') or (cands[0] if cands else None)
if action is None:
    result = {'action': None}
else:
    action.trigger()
    tb = mw.findChild(QToolBar, 'mLayerToolBar')
    result = {'action': action.objectName(), 'checked': action.isChecked(), 'toolbar_visible': tb.isVisible() if tb else None}"}
